//! Racket: `azul.rkt` (generated by `doc/src/codegen/v2/lang_racket`,
//! `ffi/unsafe`, `(require "azul.rkt")`).
//!
//! Spellings: every function has a kebab-case wrapper `<class>-<method>`
//! (`(css-property-text-color x)`, variant constructors `(layout-width-px pv)`,
//! `(layout-width-auto)`), C-like enum members are integer constants
//! `AzLayoutDisplay_Flex`, structs are `define-cstruct`s built positionally
//! (`(make-AzColorU 255 0 0 255)`), a hand-built union variant is its
//! variant struct's fields set BY NAME in the union's memory (`css-union`
//! below: `set-AzLayoutWidthValue_Variant_Exact-variant-tag!` / `-payload!`),
//! never the positional `make-..._Variant_..`, whose argument list also has
//! the padding the binding puts between tag and payload. A Vec is copied
//! from a `malloc`ed array (`css-vec`), a string is
//! `(string->azul-string "..")`.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Expr, Item, Module, Prim},
    lang::{
        escape_quoted, item_comments, item_doc, module_any, unicode_u4, variant_ctor_method,
        ExprSyntax,
    },
    CodegenBackend, GeneratedFile,
};

/// The Racket printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Racket;

/// `sanitize_racket_ident` of `lang_racket/mod.rs`.
const RESERVED: &[&str] = &[
    "define", "lambda", "let", "let*", "letrec", "if", "cond", "case", "when", "unless", "begin",
    "set!", "quote", "quasiquote", "require", "provide", "struct", "and", "or", "do", "for",
    "map", "list", "car", "cdr", "else",
];

/// `kebab` of `lang_racket/mod.rs`.
fn kebab(name: &str) -> String {
    let mut out = String::new();
    let mut prev_lower = false;
    let mut prev_digit = false;
    for c in name.chars() {
        if c == '_' || c == '-' {
            if !out.is_empty() && !out.ends_with('-') {
                out.push('-');
            }
            prev_lower = false;
            prev_digit = false;
        } else if c.is_uppercase() {
            if (prev_lower || prev_digit) && !out.is_empty() && !out.ends_with('-') {
                out.push('-');
            }
            out.push(c.to_ascii_lowercase());
            prev_lower = false;
            prev_digit = false;
        } else {
            out.push(c);
            prev_lower = c.is_ascii_lowercase();
            prev_digit = c.is_ascii_digit();
        }
    }
    while out.contains("--") {
        out = out.replace("--", "-");
    }
    if RESERVED.contains(&out.as_str()) {
        format!("{out}_")
    } else {
        out
    }
}

/// `public_name` of `lang_racket/wrappers.rs` (never `new` here).
fn wrapper(class: &str, c_method: &str) -> String {
    format!("{}-{}", kebab(class), kebab(c_method))
}

/// `(f a b)`, one argument per line when `broken`.
fn form(f: String, args: Vec<Doc>, broken: bool) -> Doc {
    if args.is_empty() {
        return Doc::text(format!("({f})"));
    }
    let open = if broken {
        format!("({f}")
    } else {
        format!("({f} ")
    };
    Doc::list(&open, args, " ", ")", false, broken, false)
}

/// A Racket string literal (`\u` / `\U` escapes keep it ASCII).
fn quoted(s: &str) -> String {
    format!("\"{}\"", escape_quoted(s, &[], &unicode_u4))
}

impl ExprSyntax for Racket {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        match text {
            "nan" => "+nan.0".to_string(),
            "inf" => "+inf.0".to_string(),
            "-inf" => "-inf.0".to_string(),
            _ => text.to_string(),
        }
    }

    fn boolean(&self, b: bool) -> String {
        String::from(if b { "#t" } else { "#f" })
    }

    fn string(&self, s: &str) -> Doc {
        form("string->azul-string".to_string(), vec![Doc::text(quoted(s))], false)
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        form(wrapper(class, &snake_to_lower_camel(method)), args, broken)
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("Az{ty}_{variant}")),
            EnumShape::Tagged => form(wrapper(ty, &variant_ctor_method(variant)), args, broken),
            // By field name: see `CSS_UNION`.
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                let vs = format!("Az{ty}_Variant_{variant}");
                let mut parts = vec![
                    Doc::text(format!("_Az{ty}")),
                    Doc::text(format!("{vs}-tag")),
                    Doc::text(format!("set-{vs}-variant-tag!")),
                    Doc::text(format!("Az{ty}_Tag_{variant}")),
                ];
                if let Some(payload) = args.into_iter().next() {
                    parts.push(Doc::text(format!("set-{vs}-payload!")));
                    parts.push(payload);
                }
                form("css-union".to_string(), parts, broken)
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let values = fields.into_iter().map(|(_, v)| v).collect();
        form(format!("make-Az{ty}"), values, broken)
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return form(wrapper(ty, "create"), Vec::new(), false);
        }
        form(
            "css-vec".to_string(),
            vec![
                Doc::text(wrapper(ty, "copyFromPtr")),
                Doc::text(format!("_Az{elem}")),
                form("list".to_string(), items, broken),
            ],
            broken,
        )
    }

    fn unsupported(&self, what: &str) -> Doc {
        form(
            "error".to_string(),
            vec![Doc::text(quoted(&format!("not expressible: {what}")))],
            false,
        )
    }
}

const CSS_VEC: &str = r";; Copies ITEMS into a malloc'ed array of TYPE; COPY clones them into a Vec.
(define (css-vec copy type items)
  (define n (length items))
  (define arr (malloc (max 1 n) type))
  (for ([item (in-list items)] [i (in-naturals)])
    (ptr-set! arr type i item))
  (copy arr n))
";

/// The union helper. It sets the variant struct's fields by name (through
/// the `define-cstruct` setters, on the union memory tagged as the variant
/// struct), so the padding the binding puts between `variant-tag` and
/// `payload` (where Rust puts the payload) needs no value here.
const CSS_UNION: &str = r";; A union value of TYPE holding one variant. The variant struct's `variant-tag`
;; and `payload` are set by name (VARIANT-TAG is the struct's pointer tag), so
;; the padding the binding puts between them needs no value.
(define (css-union type variant-tag set-tag! tag [set-payload! #f] [payload #f])
  (define p (malloc type))
  (cpointer-push-tag! p variant-tag)
  (set-tag! p tag)
  (when set-payload! (set-payload! p payload))
  (ptr-ref p type))
";

fn fn_name(item: &Item) -> String {
    item.name.kebab()
}

fn is_union(e: &Expr) -> bool {
    matches!(
        e,
        Expr::Variant {
            shape: EnumShape::Generic { .. } | EnumShape::TaggedShadowed,
            ..
        }
    )
}

fn item_fn(item: &Item) -> (bool, String) {
    let mut out = String::new();
    for line in &item_comments(&Racket, item) {
        out.push_str(&format!(";; {line}\n"));
    }
    let name = fn_name(item);
    match item_doc(&Racket, item) {
        Ok(doc) => {
            out.push_str(&format!("(define ({name})\n  {})\n", render(&doc, "  ", 1)));
            (true, out)
        }
        Err(reason) => {
            out.push_str(&format!(
                ";; {name}: not expressible with the Racket bindings: {reason}\n"
            ));
            (false, out)
        }
    }
}

impl CodegenBackend for Racket {
    fn lang(&self) -> &'static str {
        "racket"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["rkt"]
    }

    fn display_name(&self) -> &'static str {
        "Racket"
    }

    fn extension(&self) -> &'static str {
        "rkt"
    }

    fn emit_module(&self, m: &Module) -> String {
        let fns: Vec<(bool, String, String)> = m
            .items
            .iter()
            .map(|i| {
                let (ok, body) = item_fn(i);
                (ok, fn_name(i), body)
            })
            .collect();
        let mut out = String::from(
            "#lang racket/base\n;; Generated by azul-css codegen (Racket). Do not edit by \
             hand.\n(require ffi/unsafe \"azul.rkt\")\n(provide",
        );
        for (ok, name, _) in &fns {
            if *ok {
                out.push_str(&format!(" {name}"));
            }
        }
        out.push_str(")\n");
        if module_any(m, &|e| matches!(e, Expr::Vec { .. })) {
            out.push('\n');
            out.push_str(CSS_VEC);
        }
        if module_any(m, &is_union) {
            out.push('\n');
            out.push_str(CSS_UNION);
        }
        for (_, _, body) in &fns {
            out.push('\n');
            out.push_str(body);
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "#lang racket/base\n;; Copy target/codegen/azul.rkt and libazul here, then:\n;;   \
             AZ_LIB_DIR=. racket main.rkt\n(require \"azul.rkt\" \"styles.rkt\")\n",
        );
        for item in m.items.iter().filter(|i| item_fn(i).0) {
            let name = fn_name(item);
            main.push_str(&format!(
                "\n(define {name}-value ({name}))\n(printf \"{name}: ~a properties~n\" (Az{}-len \
                 {name}-value))\n",
                item.ty
            ));
        }
        vec![
            GeneratedFile {
                path: "styles.rkt".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.rkt".to_string(),
                contents: main,
            },
        ]
    }
}
